export function validatePath(commands){if(!Array.isArray(commands)||!commands.length||commands.length>2000)throw Error('Invalid vector path.');let started=false;for(const c of commands){if(!Array.isArray(c)||!['M','L','C','Z'].includes(c[0])||c.length!=={M:3,L:3,C:7,Z:1}[c[0]]||c.slice(1).some(v=>!Number.isFinite(v)||Math.abs(v)>1e7)||!started&&c[0]!=='M')throw Error('Invalid vector path.');started=c[0]!=='Z';}return commands;}
export function mapPath(commands,fn){return commands.map(c=>{const out=[c[0]];for(let i=1;i<c.length;i+=2)out.push(...fn(c[i],c[i+1]));return out;});}
export function pathToWorld(l){const sx=l.width/(l.pathWidth||l.width),sy=l.height/(l.pathHeight||l.height),a=(l.rotation||0)*Math.PI/180,c=Math.cos(a),s=Math.sin(a),cx=l.x+l.width/2,cy=l.y+l.height/2;return mapPath(l.path,(x,y)=>{x=(x*sx-l.width/2)*(l.flipX?-1:1);y=(y*sy-l.height/2)*(l.flipY?-1:1);return[cx+x*c-y*s,cy+x*s+y*c];});}
export function setWorldPath(l,commands){const o={...l},a=-(o.rotation||0)*Math.PI/180,c=Math.cos(a),s=Math.sin(a),sx=o.width/(o.pathWidth||o.width),sy=o.height/(o.pathHeight||o.height),cx=o.x+o.width/2,cy=o.y+o.height/2,local=mapPath(commands,(x,y)=>{x-=cx;y-=cy;return[((x*c-y*s)*(o.flipX?-1:1)+o.width/2)/sx,((x*s+y*c)*(o.flipY?-1:1)+o.height/2)/sy];}),pts=local.flatMap(c=>c.slice(1)),xs=pts.filter((_,i)=>i%2===0),ys=pts.filter((_,i)=>i%2===1),x=Math.min(...xs),y=Math.min(...ys),w=Math.max(1,Math.max(...xs)-x),h=Math.max(1,Math.max(...ys)-y),dx=(x+w/2-(o.pathWidth||o.width)/2)*sx*(o.flipX?-1:1),dy=(y+h/2-(o.pathHeight||o.height)/2)*sy*(o.flipY?-1:1);Object.assign(l,{path:mapPath(local,(a,b)=>[a-x,b-y]),pathWidth:w,pathHeight:h,width:w*sx,height:h*sy,x:cx+dx*c+dy*s-w*sx/2,y:cy-dx*s+dy*c-h*sy/2});}
export function pathNodes(commands){const subs=[];let sub=null;for(const c of commands){if(c[0]==='M'){sub={closed:false,nodes:[{x:c[1],y:c[2],inX:c[1],inY:c[2],outX:c[1],outY:c[2]}]};subs.push(sub);}else if(c[0]==='L'||c[0]==='C'){const prev=sub.nodes.at(-1),[x,y]=c.slice(-2),n={x,y,inX:x,inY:y,outX:x,outY:y};if(c[0]==='C'){prev.outX=c[1];prev.outY=c[2];n.inX=c[3];n.inY=c[4];}sub.nodes.push(n);}else if(c[0]==='Z'&&sub){sub.closed=true;const a=sub.nodes[0],b=sub.nodes.at(-1);if(sub.nodes.length>1&&Math.hypot(a.x-b.x,a.y-b.y)<1e-5){a.inX=b.inX;a.inY=b.inY;sub.nodes.pop();}sub=null;}}return subs;}
export function nodesPath(subs){const out=[];for(const{nodes:n,closed}of subs){if(!n.length)continue;out.push(['M',n[0].x,n[0].y]);for(let i=1;i<n.length+(closed?1:0);i++){const a=n[i-1],b=n[i%n.length];out.push(['C',a.outX,a.outY,b.inX,b.inY,b.x,b.y]);}if(closed)out.push(['Z']);}return out;}
export function translateNode(n,x,y,part='anchor',symmetric=false){if(part==='anchor'){const dx=x-n.x,dy=y-n.y;n.x=x;n.y=y;n.inX+=dx;n.inY+=dy;n.outX+=dx;n.outY+=dy;}else{const k=part==='in'?'in':'out',o=k==='in'?'out':'in';n[k+'X']=x;n[k+'Y']=y;if(symmetric){n[o+'X']=2*n.x-x;n[o+'Y']=2*n.y-y;}}}
export function tracePath(x,commands){x.beginPath();for(const c of commands){if(c[0]==='M')x.moveTo(c[1],c[2]);else if(c[0]==='L')x.lineTo(c[1],c[2]);else if(c[0]==='C')x.bezierCurveTo(...c.slice(1));else x.closePath();}}
export function selectionPath(s){if(s.type==='polygon')return s.points.map((p,i)=>[i?'L':'M',...p]).concat([['Z']]);if(s.type==='rect'){const{x,y,width:w,height:h}=s;return[['M',x,y],['L',x+w,y],['L',x+w,y+h],['L',x,y+h],['Z']];}if(s.type==='ellipse'){const{x,y,width:w,height:h}=s,cx=x+w/2,cy=y+h/2,k=.5522847498307936,rx=w/2,ry=h/2;return[['M',cx+rx,cy],['C',cx+rx,cy+k*ry,cx+k*rx,cy+ry,cx,cy+ry],['C',cx-k*rx,cy+ry,cx-rx,cy+k*ry,cx-rx,cy],['C',cx-rx,cy-k*ry,cx-k*rx,cy-ry,cx,cy-ry],['C',cx+k*rx,cy-ry,cx+rx,cy-k*ry,cx+rx,cy],['Z']];}throw Error('Vùng chọn pixel: lưu vào kênh alpha. Work Path dùng rect, ellipse hoặc polygon.');}
